package ru.fkit.bi.analytics.stateconfiguration;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import ru.fkit.bi.analytics.api.BusinessException;

@Service
public class StateConfigurationService {
  private static final Set<String> STATES=Set.of("RUN","IDLE","DOWN","SETUP","PLANNED_STOP");
  private static final Set<String> OPERATORS=Set.of("EQ","NE","GT","GTE","LT","LTE","BETWEEN","IN");
  private final JdbcTemplate jdbc;private final ObjectMapper json;private final TransactionTemplate transactions;
  public StateConfigurationService(JdbcTemplate jdbc,ObjectMapper json,TransactionTemplate transactions){this.jdbc=jdbc;this.json=json;this.transactions=transactions;}

  public Object get(UUID machine){requireMachine(machine);return jdbc.query("select configuration,updated_at from analytics.machine_state_config where machine_id=?",(r,n)->response(machine,(ObjectNode)read(r.getString(1)),r.getTimestamp(2).toInstant()),machine).stream().findFirst().orElseThrow(()->notFound("Machine state configuration"));}
  public Object validate(UUID machine,JsonNode input){requireMachine(machine);Result result=validateDocument(machine,input);Map<String,Object> out=new LinkedHashMap<>();out.put("valid",result.errors.isEmpty());out.put("normalizedConfiguration",result.errors.isEmpty()?result.normalized:null);out.put("errors",result.errors);out.put("warnings",result.warnings);out.put("checkedAt",Instant.now());return out;}
  public Object replace(UUID machine,JsonNode input){return transactions.execute(s->{lockMachine(machine);requireMachine(machine);Result result=validateDocument(machine,input);if(!result.errors.isEmpty())throw new BusinessException(422,"STATE_CONFIGURATION_INVALID","State configuration validation failed",List.of(),Map.of("errors",result.errors));String body=write(result.normalized);jdbc.update("insert into analytics.machine_state_config(machine_id,configuration) values (?,?::jsonb) on conflict(machine_id) do update set configuration=excluded.configuration,updated_at=current_timestamp",machine,body);return get(machine);});}

  public void lock(UUID machine){jdbc.query("select machine_id from analytics.machine_state_config where machine_id=? for update",(r,n)->r.getObject(1),machine);}

  public List<Map<String,Object>> activationErrors(UUID machine){List<Map<String,Object>> errors=new ArrayList<>();JsonNode config=jdbc.query("select configuration from analytics.machine_state_config where machine_id=?",(r,n)->read(r.getString(1)),machine).stream().findFirst().orElse(null);if(config==null){errors.add(issue("STATE_CONFIGURATION_REQUIRED","Machine state configuration is required","configuration"));return errors;}Result result=validateDocument(machine,config);errors.addAll(result.errors);return errors;}
  public List<Map<String,Object>> activationWarnings(UUID machine){List<Map<String,Object>> warnings=new ArrayList<>();Boolean hasRate=jdbc.queryForObject("select exists(select 1 from equipment.machine where id=? and nominal_rate is not null and production_unit_code is not null)",Boolean.class,machine);if(!Boolean.TRUE.equals(hasRate))warnings.add(issue("MACHINE_RATE_MISSING","Production performance is unavailable without nominal rate and production unit","nominalRate"));for(String semantic:List.of("PRODUCTION_COUNT","SCRAP_COUNT")){Boolean found=jdbc.queryForObject("select exists(select 1 from equipment.telemetry_signal where machine_id=? and semantic_code=? and status='ACTIVE')",Boolean.class,machine,semantic);if(!Boolean.TRUE.equals(found))warnings.add(issue("SIGNAL_MISSING","Optional signal "+semantic+" is not configured","signals"));}Boolean featured=jdbc.queryForObject("select exists(select 1 from equipment.telemetry_signal where machine_id=? and featured and status='ACTIVE')",Boolean.class,machine);if(!Boolean.TRUE.equals(featured))warnings.add(issue("FEATURED_SIGNAL_MISSING","No active featured signals are configured","signals"));return warnings;}

  private Result validateDocument(UUID machine,JsonNode input){List<Map<String,Object>> errors=new ArrayList<>(),warnings=new ArrayList<>();if(!(input instanceof ObjectNode source)){errors.add(issue("CONFIGURATION_OBJECT_REQUIRED","Configuration must be an object",""));return new Result(null,errors,warnings);}ObjectNode normalized=source.deepCopy();fields(source,Set.of("defaultState","offlineAfterMs","rules"),"",errors);String defaultState=text(source,"defaultState");if(!STATES.contains(defaultState))errors.add(issue("DEFAULT_STATE_INVALID","defaultState must be a user machine state","defaultState"));long offline=longValue(source.get("offlineAfterMs"),-1);if(offline<1)errors.add(issue("OFFLINE_AFTER_INVALID","offlineAfterMs must be a positive integer","offlineAfterMs"));JsonNode rules=source.get("rules");if(!(rules instanceof ArrayNode array)){errors.add(issue("RULES_ARRAY_REQUIRED","rules must be an array","rules"));return new Result(normalized,errors,warnings);}if(array.size()<1||array.size()>20)errors.add(issue("RULE_COUNT_INVALID","rules must contain 1..20 entries","rules"));Set<Integer> priorities=new HashSet<>();Set<UUID> ids=new HashSet<>();ArrayNode outRules=json.createArrayNode();int[] nodeCount={0};int idx=0;for(JsonNode rule:array){ObjectNode nr=rule instanceof ObjectNode o?o.deepCopy():json.createObjectNode();String p="rules["+idx+"]";if(!(rule instanceof ObjectNode)){errors.add(issue("RULE_OBJECT_REQUIRED","Rule must be an object",p));outRules.add(nr);idx++;continue;}fields(rule,Set.of("id","name","priority","targetState","enterCondition","exitCondition","activationDelayMs","releaseDelayMs"),p,errors);UUID ruleId=uuid(rule.get("id"));if(rule.hasNonNull("id")&&ruleId==null)errors.add(issue("RULE_ID_INVALID","Rule id must be a UUID or null",p+".id"));if(ruleId==null){ruleId=UUID.randomUUID();nr.put("id",ruleId.toString());}if(!ids.add(ruleId))errors.add(issue("RULE_ID_DUPLICATE","Rule ids must be unique",p+".id",ruleId));String name=text(rule,"name");if(name==null||name.isBlank()||name.length()>200)errors.add(issue("RULE_NAME_INVALID","Rule name is required and must be at most 200 characters",p+".name",ruleId));Integer priority=intValue(rule.get("priority"));if(priority==null||!priorities.add(priority))errors.add(issue("RULE_PRIORITY_INVALID","Rule priorities must be integers and unique",p+".priority",ruleId));if(!STATES.contains(text(rule,"targetState")))errors.add(issue("RULE_TARGET_STATE_INVALID","targetState must be a user state; OFFLINE is reserved",p+".targetState",ruleId));long activation=longValue(rule.get("activationDelayMs"),-1),release=longValue(rule.get("releaseDelayMs"),-1);if(activation<0)errors.add(issue("ACTIVATION_DELAY_INVALID","activationDelayMs must be a non-negative integer",p+".activationDelayMs",ruleId));if(release<0)errors.add(issue("RELEASE_DELAY_INVALID","releaseDelayMs must be a non-negative integer",p+".releaseDelayMs",ruleId));validateCondition(machine,rule.get("enterCondition"),p+".enterCondition",1,nodeCount,errors,ruleId);JsonNode exit=rule.get("exitCondition");if(exit!=null&&!exit.isNull())validateCondition(machine,exit,p+".exitCondition",1,nodeCount,errors,ruleId);outRules.add(nr);idx++;}normalized.set("rules",outRules);return new Result(normalized,errors,warnings);}

  private void validateCondition(UUID machine,JsonNode node,String path,int depth,int[] count,List<Map<String,Object>> errors,UUID ruleId){count[0]++;if(depth>10){errors.add(issue("AST_DEPTH_EXCEEDED","Condition tree depth cannot exceed 10",path,ruleId));return;}if(count[0]>100){if(count[0]==101)errors.add(issue("AST_NODE_LIMIT_EXCEEDED","Condition tree cannot exceed 100 nodes",path,ruleId));return;}if(!(node instanceof ObjectNode)){errors.add(issue("CONDITION_OBJECT_REQUIRED","Condition must be an object",path,ruleId));return;}String type=text(node,"type");switch(type==null?"":type){case "ALL","ANY"->{fields(node,Set.of("type","conditions"),path,errors,ruleId);JsonNode children=node.get("conditions");if(!(children instanceof ArrayNode a)||a.isEmpty()){errors.add(issue("CONDITION_CHILDREN_REQUIRED","ALL and ANY require at least one child",path+".conditions",ruleId));return;}for(int i=0;i<a.size();i++)validateCondition(machine,a.get(i),path+".conditions["+i+"]",depth+1,count,errors,ruleId);}case "NOT"->{fields(node,Set.of("type","condition"),path,errors,ruleId);if(!node.has("condition"))errors.add(issue("NOT_CHILD_REQUIRED","NOT requires one child condition",path+".condition",ruleId));else validateCondition(machine,node.get("condition"),path+".condition",depth+1,count,errors,ruleId);}case "COMPARE"->validateCompare(machine,node,path,errors,ruleId);default->errors.add(issue("CONDITION_TYPE_INVALID","Condition type must be ALL, ANY, NOT or COMPARE",path+".type",ruleId));}}

  private void validateCompare(UUID machine,JsonNode n,String path,List<Map<String,Object>> errors,UUID ruleId){String op=text(n,"operator");if(!OPERATORS.contains(op)){errors.add(issue("OPERATOR_INVALID","Unsupported comparison operator",path+".operator",ruleId));return;}UUID signal=uuid(n.get("signalId"));if(signal==null){errors.add(issue("SIGNAL_ID_INVALID","signalId must be a UUID",path+".signalId",ruleId));return;}SignalInfo info=jdbc.query("select value_type,status,stale_after_ms from equipment.telemetry_signal where id=? and machine_id=?",(r,x)->new SignalInfo(r.getString(1),r.getString(2),(Long)r.getObject(3)),signal,machine).stream().findFirst().orElse(null);if(info==null){errors.add(issue("SIGNAL_REFERENCE_INVALID","Signal must belong to this machine",path+".signalId",ruleId));return;}if(!"ACTIVE".equals(info.status))errors.add(issue("SIGNAL_DISABLED","Referenced signal must be active",path+".signalId",ruleId));if(info.stale==null)errors.add(issue("SIGNAL_STALE_AFTER_REQUIRED","Referenced signal requires staleAfterMs",path+".signalId",ruleId));boolean numeric=Set.of("DOUBLE","LONG").contains(info.type);Set<String> supported=switch(info.type){case "DOUBLE"->Set.of("EQ","NE","GT","GTE","LT","LTE","BETWEEN");case "LONG"->Set.of("EQ","NE","GT","GTE","LT","LTE","BETWEEN","IN");case "BOOLEAN"->Set.of("EQ","NE");case "STRING"->Set.of("EQ","NE","IN");default->Set.of();};if(!supported.contains(op))errors.add(issue("OPERATOR_TYPE_MISMATCH","Operator is not supported for signal valueType "+info.type,path+".operator",ruleId));Set<String> allowed=new HashSet<>(Set.of("type","signalId","operator"));switch(op){case "EQ","NE"->{allowed.add("value");if("DOUBLE".equals(info.type))allowed.add("tolerance");if(!n.has("value"))errors.add(issue("COMPARE_VALUE_REQUIRED","Operator requires value",path+".value",ruleId));validateLiteral(n.get("value"),info.type,path+".value",errors,ruleId);if("DOUBLE".equals(info.type)){double tol=doubleValue(n.get("tolerance"),Double.NaN);if(!Double.isFinite(tol)||tol<=0)errors.add(issue("DOUBLE_TOLERANCE_REQUIRED","DOUBLE EQ and NE require a finite tolerance greater than zero",path+".tolerance",ruleId));}}case "GT","GTE","LT","LTE"->{allowed.add("value");if(!n.has("value"))errors.add(issue("COMPARE_VALUE_REQUIRED","Operator requires value",path+".value",ruleId));validateLiteral(n.get("value"),info.type,path+".value",errors,ruleId);}case "BETWEEN"->{allowed.add("lower");allowed.add("upper");if(!n.has("lower")||!n.has("upper"))errors.add(issue("BETWEEN_BOUNDS_REQUIRED","BETWEEN requires lower and upper",path,ruleId));validateLiteral(n.get("lower"),info.type,path+".lower",errors,ruleId);validateLiteral(n.get("upper"),info.type,path+".upper",errors,ruleId);if(n.path("lower").isNumber()&&n.path("upper").isNumber()&&n.path("lower").asDouble()>n.path("upper").asDouble())errors.add(issue("BETWEEN_BOUNDS_ORDER_INVALID","lower cannot exceed upper",path,ruleId));}case "IN"->{allowed.add("values");JsonNode values=n.get("values");if(!(values instanceof ArrayNode a)||a.isEmpty()||a.size()>50)errors.add(issue("IN_VALUES_INVALID","IN requires 1..50 values",path+".values",ruleId));else{Set<JsonNode> unique=new HashSet<>();for(int i=0;i<a.size();i++){validateLiteral(a.get(i),info.type,path+".values["+i+"]",errors,ruleId);if(!unique.add(a.get(i)))errors.add(issue("IN_VALUES_DUPLICATE","IN values must be unique",path+".values["+i+"]",ruleId));}}}}fields(n,allowed,path,errors,ruleId);}

  private void validateLiteral(JsonNode n,String type,String path,List<Map<String,Object>> errors,UUID ruleId){boolean valid=n!=null&&switch(type){case "DOUBLE"->n.isNumber()&&Double.isFinite(n.asDouble());case "LONG"->n.isIntegralNumber()&&n.canConvertToLong();case "BOOLEAN"->n.isBoolean();case "STRING"->n.isTextual();default->false;};if(!valid)errors.add(issue("LITERAL_TYPE_MISMATCH","Literal must match signal valueType "+type,path,ruleId));}
  private void fields(JsonNode n,Set<String> allowed,String path,List<Map<String,Object>> errors){fields(n,allowed,path,errors,null);}
  private void fields(JsonNode n,Set<String> allowed,String path,List<Map<String,Object>> errors,UUID ruleId){n.fieldNames().forEachRemaining(k->{if(!allowed.contains(k))errors.add(issue("UNKNOWN_FIELD","Unexpected field",path.isEmpty()?k:path+"."+k,ruleId));});}
  private static String text(JsonNode n,String key){return n!=null&&n.hasNonNull(key)&&n.get(key).isTextual()?n.get(key).asText():null;}
  private static UUID uuid(JsonNode n){try{return n!=null&&n.isTextual()?UUID.fromString(n.asText()):null;}catch(Exception e){return null;}}
  private static Integer intValue(JsonNode n){return n!=null&&n.isIntegralNumber()&&n.canConvertToInt()?n.intValue():null;}
  private static long longValue(JsonNode n,long fallback){return n!=null&&n.isIntegralNumber()&&n.canConvertToLong()?n.longValue():fallback;}
  private static double doubleValue(JsonNode n,double fallback){return n!=null&&n.isNumber()?n.doubleValue():fallback;}
  private JsonNode read(String s){try{return json.readTree(s);}catch(Exception e){throw new IllegalArgumentException(e);}}
  private String write(JsonNode n){try{return json.writeValueAsString(n);}catch(Exception e){throw new IllegalArgumentException(e);}}
  private Object response(UUID m,ObjectNode config,Instant at){Map<String,Object> out=json.convertValue(config,Map.class);out.put("machineId",m);out.put("updatedAt",at);return out;}
  private void requireMachine(UUID m){if(!Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from equipment.machine where id=?)",Boolean.class,m)))throw notFound("Machine");}
  private void lockMachine(UUID m){jdbc.query("select id from equipment.machine where id=? for update",(r,n)->r.getObject(1),m);}
  private static Map<String,Object> issue(String code,String message,String path){Map<String,Object> m=new LinkedHashMap<>();m.put("code",code);m.put("message",message);m.put("path",path);return m;}
  private static Map<String,Object> issue(String code,String message,String path,UUID rule){Map<String,Object> m=issue(code,message,path);m.put("resourceId",rule);return m;}
  private static BusinessException notFound(String what){return new BusinessException(404,"NOT_FOUND",what+" not found");}
  private record Result(ObjectNode normalized,List<Map<String,Object>> errors,List<Map<String,Object>> warnings){}
  private record SignalInfo(String type,String status,Long stale){}
}
